#include <Arduino.h>
#include <TM1637Display.h>
#include <DHT.h>
#include <math.h>

TM1637Display display(4, 5);
DHT dht(7, DHT11);
struct Button {
  uint8_t pin;
  int raw;
  int stable;
  unsigned long changed;
};
Button nextButton = {2, HIGH, HIGH, 0};
Button confirmButton = {3, HIGH, HIGH, 0};
uint8_t selected = 0;
bool confirmed = false;
float temperatureValue = NAN;
float humidityValue = NAN;
unsigned long lastSensor = 0;
unsigned long lastDisplay = 0;
bool firstSensor = true;

bool pressed(Button &b, unsigned long now) {
  int value = digitalRead(b.pin);
  if (value != b.raw) {
    b.raw = value;
    b.changed = now;
  }
  if (b.stable != b.raw && now - b.changed >= 35) {
    b.stable = b.raw;
    return b.stable == LOW;
  }
  return false;
}

void setup() {
  pinMode(2, INPUT_PULLUP);
  pinMode(3, INPUT_PULLUP);
  dht.begin();
  display.setBrightness(4);
  display.showNumberDec(1);
}

void loop() {
  unsigned long now = millis();
  if (pressed(nextButton, now)) {
    selected = (selected + 1) % 3;
    confirmed = false;
  }
  if (pressed(confirmButton, now)) confirmed = true;
  if (firstSensor || now - lastSensor >= 2000) {
    firstSensor = false;
    lastSensor = now;
    float t = dht.readTemperature();
    float h = dht.readHumidity();
    if (!isnan(t)) temperatureValue = t;
    if (!isnan(h)) humidityValue = h;
  }
  if (now - lastDisplay >= 100) {
    lastDisplay = now;
    if (!confirmed) {
      display.showNumberDec(selected + 1);
    } else if (selected == 2) {
      display.showNumberDec(analogRead(A0));
    } else {
      float value = selected == 0 ? temperatureValue : humidityValue;
      if (!isnan(value)) display.showNumberDec((int)round(value));
      else {
        const uint8_t missing[4] = {0x40, 0x40, 0x40, 0x40};
        display.setSegments(missing);
      }
    }
  }
}
